def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = op.count('C')
    opp_d = n - opp_c
    my_d = me.count('D')

    last_op = op[-1]
    last_me = me[-1]

    rounds_left = 100 - n

    # cooperation streak of opponent
    c_run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            c_run += 1
        else:
            break

    # defection streak of opponent
    d_run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            d_run += 1
        else:
            break

    opp_rate = opp_c / n

    # Endgame: exploit an opponent who has been almost purely cooperative
    if rounds_left <= 2:
        if last_op == 'C':
            return 'D'
        return 'D'

    # Heavily cooperative opponent: lock in mutual cooperation, rare final exploitation
    if opp_d == 0:
        if rounds_left <= 4:
            return 'D'
        return 'C'

    # Opponent almost never defects: cooperate, but take a late cheap shot
    if opp_rate >= 0.93 and d_run == 0:
        if rounds_left <= 3:
            return 'D'
        return 'C'

    # Opponent heavily defective: punish, with rare forgiving probe
    if opp_rate <= 0.2:
        if d_run >= 3 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Strongly exploitative opponent
    if opp_rate <= 0.35:
        if last_op == 'D':
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Opponent just defected
    if last_op == 'D':
        if d_run >= 3:
            # stuck in defection spiral: mostly punish, occasionally restart
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        if d_run == 2:
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        # single defection: retaliate but forgive often to keep cooperation alive
        if opp_rate > 0.6:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated: cooperate, but test heavy cooperators occasionally
    if c_run >= 8 and opp_rate > 0.75 and rounds_left > 10:
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # If we've been defecting more than opponent, return to cooperation
    if my_d > opp_d + 2:
        return 'C'

    return 'C'
